pub fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    assert!(!sep.is_empty(), "separator must be non-empty");

    let mut out: Vec<Vec<String>> = Vec::with_capacity(a.len());

    for s in a {
        // If maxsplit == 0, no splitting is performed.
        if maxsplit == 0 {
            out.push(vec![s]);
            continue;
        }

        // Rust's rsplitn(n, pat) returns at most n parts.
        // We need at most (maxsplit + 1) parts, so n = maxsplit + 1.
        let n = (maxsplit as usize).saturating_add(1);

        let mut parts: Vec<String> = s.rsplitn(n, &sep).map(|p| p.to_string()).collect();
        parts.reverse(); // match left-to-right order of parts

        // Ensure each inner list is non-empty even for empty input strings.
        if parts.is_empty() {
            parts.push(String::new());
        }

        out.push(parts);
    }

    out
}